import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def components(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                comps.append((c,cells))
    return comps

def transform(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    lines=[] # (type, idx, color)
    for c,cells in components(g):
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        n=len(cells)
        if n>=3:
            if min(ys)==max(ys):  # horizontal line
                lines.append(('r',ys[0],c))
            elif min(xs)==max(xs):
                lines.append(('c',xs[0],c))
            elif n==9 and max(ys)-min(ys)==2 and max(xs)-min(xs)==2:
                lines.append(('r',(min(ys)+max(ys))//2,c))
                lines.append(('c',(min(xs)+max(xs))//2,c))
    # paint lines; intersections of two lines -> 0
    for r in range(H):
        for col in range(W):
            hit=[(t,i,c) for t,i,c in lines if (t=='r' and i==r) or (t=='c' and i==col)]
            if len(hit)>=2: out[r][col]=0
            elif len(hit)==1: out[r][col]=hit[0][2]
    return out
